/**
 * Domain model.
 *
 * The shape below is deliberately *normalised* (exercises / sessions / set
 * entries are separate collections joined by id) so the exact same model maps
 * 1:1 onto the SQLite schema in `db/schema.sql`. Swapping the localStorage
 * driver for SQLite later means reimplementing `lib/storage.ts` only — no
 * component and no selector has to change.
 */

/** Opaque identifier. Generated by `createId()` in `lib/utils.ts`. */
export type Id = string;

/** Calendar day in `YYYY-MM-DD`, always in the user's local timezone. */
export type IsoDate = string;

export const MUSCLE_GROUPS = [
  "chest",
  "back",
  "shoulders",
  "biceps",
  "triceps",
  "quads",
  "hamstrings",
  "glutes",
  "calves",
  "core",
] as const;

export type MuscleGroup = (typeof MUSCLE_GROUPS)[number];

export const MUSCLE_GROUP_LABELS: Record<MuscleGroup, string> = {
  chest: "الصدر",
  back: "الظهر",
  shoulders: "الأكتاف",
  biceps: "الباي",
  triceps: "التراي",
  quads: "أمامية الفخذ",
  hamstrings: "خلفية الفخذ",
  glutes: "الجلوت",
  calves: "البطة",
  core: "البطن",
};

export interface Exercise {
  id: Id;
  name: string;
  muscleGroup: MuscleGroup;
  /** Free text: "machine", "cable", "barbell"… used for grouping only. */
  equipment: string;
  createdAt: number;
  archived: boolean;
}

/** One template day of the training split (Push / Pull / Legs / …). */
export interface ProgramDay {
  id: Id;
  /** Stable machine name used in URLs and defaults: `push`, `pull`, … */
  slug: string;
  /** Latin display name, e.g. "Push". */
  name: string;
  /** Arabic subtitle describing the target muscles. */
  focus: string;
  exerciseIds: Id[];
  order: number;
}

/** A training day that actually happened. */
export interface Session {
  id: Id;
  date: IsoDate;
  /** Which template day it was based on. `null` for an ad-hoc session. */
  programDayId: Id | null;
  note: string;
  createdAt: number;
  updatedAt: number;
}

/** A single logged set. This is the atomic fact the whole app is built on. */
export interface SetEntry {
  id: Id;
  sessionId: Id;
  exerciseId: Id;
  /** 1-based position of the set inside the session, per exercise. */
  setIndex: number;
  /** Always stored in kilograms; display units are a presentation concern. */
  weightKg: number;
  reps: number;
  /** Rate of perceived exertion, 1–10. Optional. */
  rpe: number | null;
  /** Warm-up sets are excluded from volume and PR maths. */
  isWarmup: boolean;
  createdAt: number;
}

export interface NutritionLog {
  date: IsoDate;
  kcal: number;
  protein: number;
  carbs: number;
  fat: number;
}

export type WeightUnit = "kg" | "lb";

export interface Settings {
  unit: WeightUnit;
  /** Sessions per week the user is aiming for. Drives the consistency ring. */
  weeklyGoal: number;
  bodyWeightKg: number | null;
  targets: {
    kcal: number;
    protein: number;
    carbs: number;
    fat: number;
  };
}

/** The entire persisted document. One row, versioned, atomically written. */
export interface Database {
  version: number;
  exercises: Exercise[];
  programDays: ProgramDay[];
  sessions: Session[];
  setEntries: SetEntry[];
  /** Explicit gym check-ins, including rest-day cardio. Keyed by date. */
  attendance: Record<IsoDate, boolean>;
  nutrition: Record<IsoDate, NutritionLog>;
  settings: Settings;
  updatedAt: number;
}

/* ------------------------------------------------------------------ */
/* Derived, read-only view models used by the dashboard                */
/* ------------------------------------------------------------------ */

/** One point on an exercise's progression curve — one session, one exercise. */
export interface ExerciseProgressPoint {
  date: IsoDate;
  sessionId: Id;
  /** Heaviest working weight lifted that day. */
  topWeightKg: number;
  /** Reps achieved on the top set, for context on the tooltip. */
  topSetReps: number;
  /** Estimated 1-rep-max (Epley) of the best set that day. */
  estimated1rm: number;
  /** Σ weight × reps across working sets. */
  volumeKg: number;
  totalReps: number;
  /** True when `topWeightKg` beat every previous session. */
  isPr: boolean;
}

export interface VolumePoint {
  date: IsoDate;
  sessionId: Id;
  volumeKg: number;
  setCount: number;
  label: string;
}

export interface MuscleGroupVolume {
  group: MuscleGroup;
  label: string;
  volumeKg: number;
  setCount: number;
  share: number;
}

export interface PersonalRecord {
  exerciseId: Id;
  exerciseName: string;
  date: IsoDate;
  weightKg: number;
  reps: number;
  estimated1rm: number;
  /** Improvement over the previous best, in kg. `null` for a first record. */
  gainKg: number | null;
}

export interface WeeklyBucket {
  /** ISO date of the Saturday that opens the week (week starts Saturday). */
  weekStart: IsoDate;
  label: string;
  sessions: number;
  volumeKg: number;
  attended: number;
}
